    if end is None: break
    rets = []
    for t in rosters[rb]:
        p0, p1 = px(t, rb), px(t, end)
        if p0 and p1 and p0 > 0: rets.append(p1/p0 - 1)
    if rets: c *= (1 + sum(rets)/len(rets))

def dem_index(d):
