    if rb is None: return None
    rets = []
    for t in rosters[rb]:
        p0, p1 = px(t, rb), px(t, d)
        if p0 and p1 and p0 > 0: rets.append(p1/p0 - 1)
    if not rets: return None
    return cum[rb] * (1 + sum(rets)/len(rets)), len(rets)

def xbi_index(d):
