    di_s, n_s = dem_index(s)
    xi_s = xbi_index(s)
    dem = di_asof/di_s - 1
    xbi = xi_asof/xi_s - 1
    print(f"{name:4}  {s:>10}   {dem:>+12.2%}   {xbi:>+7.2%}   {dem-xbi:>+7.2%}   {n_s}/{n_asof}")
